package sessions;

import static readcode.Assert.*;

import java.util.ArrayList;
import java.util.List;

public class QuorumTest {
    private List<Replica> replicas(int n) {
        List<Replica> list = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            list.add(new Replica("r" + i));
        }
        return list;
    }

    public void testQuorumIsStrictMajority() {
        assertEquals(2, new QuorumStore(replicas(3)).quorum());
        assertEquals(3, new QuorumStore(replicas(4)).quorum());
        assertEquals(3, new QuorumStore(replicas(5)).quorum());
    }

    public void testPutThenGetWithAllReplicasUp() {
        QuorumStore store = new QuorumStore(replicas(3));
        assertTrue(store.put("k", "v1"));
        assertEquals("v1", store.get("k").get());
    }

    public void testWriteToOneOfThreeIsNotAcknowledged() {
        List<Replica> rs = replicas(3);
        rs.get(1).setUp(false);
        rs.get(2).setUp(false);
        QuorumStore store = new QuorumStore(rs);
        assertFalse(store.put("k", "lonely"), "write reached 1 of 3 replicas but was acknowledged");
    }

    public void testWriteWithMajorityAlive() {
        List<Replica> rs = replicas(5);
        rs.get(3).setUp(false);
        rs.get(4).setUp(false);
        QuorumStore store = new QuorumStore(rs);
        assertTrue(store.put("k", "v"));
    }

    public void testMinorityPartitionCannotAcknowledgeWrites() {
        List<Replica> rs = replicas(5);
        for (int i = 2; i < 5; i++) {
            rs.get(i).setUp(false);
        }
        QuorumStore store = new QuorumStore(rs);
        boolean acked = store.put("session:7", "tok-a");
        System.out.println("2-of-5 replicas up, write acknowledged: " + acked);
        assertFalse(acked, "a minority of 2 replicas acknowledged a write");
    }

    public void testReadNeedsQuorumOfReplicas() {
        List<Replica> rs = replicas(3);
        QuorumStore store = new QuorumStore(rs);
        store.put("k", "v");
        rs.get(0).setUp(false);
        rs.get(1).setUp(false);
        assertThrows(NoQuorumException.class, () -> store.get("k"));
    }

    public void testReadReturnsNewestVersionAcrossReplicas() {
        List<Replica> rs = replicas(3);
        QuorumStore store = new QuorumStore(rs);
        store.put("k", "old");
        rs.get(0).setUp(false);
        assertTrue(store.put("k", "new"));
        rs.get(0).setUp(true);
        rs.get(2).setUp(false);
        assertEquals("new", store.get("k").get());
    }

    public void testLogoutIsVisibleToSessionService() {
        QuorumStore store = new QuorumStore(replicas(3));
        SessionService sessions = new SessionService(store);
        assertTrue(sessions.login("u1", "tok"));
        assertTrue(sessions.isLoggedIn("u1", "tok"));
        assertTrue(sessions.logout("u1"));
        assertFalse(sessions.isLoggedIn("u1", "tok"));
    }
}
